def get_format(format_type, lang=None, use_l10n=None):
    """
    For a specific format type, returns the format for the current
    language (locale), defaults to the format in the settings.
    format_type is the name of the format, e.g. 'DATE_FORMAT'

    If use_l10n is provided and is not None, that will force the value to
    be localized (or not), overriding the value of settings.USE_L10N.
    """
    format_type = force_str(format_type)
    if use_l10n or (use_l10n is None and settings.USE_L10N):
        if lang is None:
            lang = get_language()
        cache_key = (format_type, lang)
        try:
            cached = _format_cache[cache_key]
            if cached is not None:
                return cached
            else:
                # Return the general setting by default
                return getattr(settings, format_type)
        except KeyError:
            for module in get_format_modules(lang):
                try:
                    val = getattr(module, format_type)
                    for iso_input in ISO_INPUT_FORMATS.get(format_type, ()):
                        if iso_input not in val:
                            if isinstance(val, tuple):
                                val = list(val)
                            val.append(iso_input)
                    _format_cache[cache_key] = val
                    return val
                except AttributeError:
                    pass
            _format_cache[cache_key] = None
    return getattr(settings, format_type)

def load_module(name):
    if os.path.exists(name) and os.path.splitext(name)[1] == '.py':
        sys.path.insert(0, os.path.dirname(os.path.abspath(name)))
        try:
            m = os.path.splitext(os.path.basename(name))[0]
            module = importlib.import_module(m)
        finally:
            sys.path.pop(0)

        return module

def where_in(values: list[Any], mark: str = "'") -> str:
    """
    Given a list of values, build a parenthesis list suitable for an IN expression.

        >>> where_in([1, "b", 3])
        (1, 'b', 3)

    """

    def quote(value: Any) -> str:
        if isinstance(value, str):
            value = value.replace(mark, mark * 2)
            return f"{mark}{value}{mark}"
        return str(value)

    joined_values = ", ".join(quote(value) for value in values)
    return f"({joined_values})"

def validate_file_name(name, allow_relative_path=False):
    # Remove potentially dangerous names
    if os.path.basename(name) in {"", ".", ".."}:
        raise SuspiciousFileOperation("Could not derive file name from '%s'" % name)

    if allow_relative_path:
        # Use PurePosixPath() because this branch is checked only in
        # FileField.generate_filename() where all file paths are expected to be
        # Unix style (with forward slashes).
        path = pathlib.PurePosixPath(name)
        if path.is_absolute() or ".." in path.parts:
            raise SuspiciousFileOperation(
                "Detected path traversal attempt in '%s'" % name
            )
    elif name != os.path.basename(name):
        raise SuspiciousFileOperation("File name '%s' includes path elements" % name)

    return name

async def massban(
    self,
    ctx: commands.Context,
    user_ids: commands.Greedy[RawUserIds],
    days: Optional[int] = None,
    *,
    reason: str = None,
):
    """Mass bans user(s) from the server.

    User IDs need to be provided in order to ban
    using this command."""
    banned = []
    errors = {}
    upgrades = []

    async def show_results():
        text = _("Banned {num} users from the server.").format(
            num=humanize_number(len(banned))
        )
        if errors:
            text += _("\nErrors:\n")
            text += "\n".join(errors.values())
        if upgrades:
            text += _(
                "\nFollowing user IDs have been upgraded from a temporary to a permanent ban:\n"
            )
            text += humanize_list(upgrades)

        for p in pagify(text):
            await ctx.send(p)

    def remove_processed(ids):
        return [_id for _id in ids if _id not in banned and _id not in errors]

    user_ids = list(set(user_ids))  # No dupes

    author = ctx.author
    guild = ctx.guild

    if not user_ids:
        await ctx.send_help()
        return

    if days is None:
        days = await self.config.guild(guild).default_days()

    if not (0 <= days <= 7):
        await ctx.send(_("Invalid days. Must be between 0 and 7."))
        return

    if not guild.me.guild_permissions.ban_members:
        return await ctx.send(_("I lack the permissions to do this."))

    tempbans = await self.config.guild(guild).current_tempbans()

    ban_list = await guild.bans()
    for entry in ban_list:
        for user_id in user_ids:
            if entry.user.id == user_id:
                if user_id in tempbans:
                    # We need to check if a user is tempbanned here because otherwise they won't be processed later on.
                    continue
                else:
                    errors[user_id] = _("User with ID {user_id} is already banned.").format(
                        user_id=user_id
                    )

    user_ids = remove_processed(user_ids)

    if not user_ids:
        await show_results()
        return

    for user_id in user_ids:
        user = guild.get_member(user_id)
        if user is not None:
            if user_id in tempbans:
                # We need to check if a user is tempbanned here because otherwise they won't be processed later on.
                continue
            else:
                # Instead of replicating all that handling... gets attr from decorator
                try:
                    success, reason = await self.ban_user(
                        user=user, ctx=ctx, days=days, reason=reason, create_modlog_case=True
                    )
                    if success:
                        banned.append(user_id)
                    else:
                        errors[user_id] = _("Failed to ban user {user_id}: {reason}").format(
                            user_id=user_id, reason=reason
                        )
                except Exception as e:
                    errors[user_id] = _("Failed to ban user {user_id}: {reason}").format(
                        user_id=user_id, reason=e
                    )

    user_ids = remove_processed(user_ids)

    if not user_ids:
        await show_results()
        return

    for user_id in user_ids:
        user = discord.Object(id=user_id)
        audit_reason = get_audit_reason(author, reason)
        queue_entry = (guild.id, user_id)
        async with self.config.guild(guild).current_tempbans() as tempbans:
            if user_id in tempbans:
                tempbans.remove(user_id)
                upgrades.append(str(user_id))
                log.info(
                    "{}({}) upgraded the tempban for {} to a permaban.".format(
                        author.name, author.id, user_id
                    )
                )
                banned.append(user_id)
            else:
                try:
                    await guild.ban(user, reason=audit_reason, delete_message_days=days)
                    log.info("{}({}) hackbanned {}".format(author.name, author.id, user_id))
                except discord.NotFound:
                    errors[user_id] = _("User with ID {user_id} not found").format(
                        user_id=user_id
                    )
                    continue
                except discord.Forbidden:
                    errors[user_id] = _(
                        "Could not ban user with ID {user_id}: missing permissions."
                    ).format(user_id=user_id)
                    continue
                else:
                    banned.append(user_id)

        await modlog.create_case(
            self.bot,
            guild,
            ctx.message.created_at.replace(tzinfo=timezone.utc),
            "hackban",
            user_id,
            author,
            reason,
            until=None,
            channel=None,
        )
    await show_results()

def save(self, name, content, max_length=None):
    """
    Save new content to the file specified by name. The content should be
    a proper File object or any Python file-like object, ready to be read
    from the beginning.
    """
    # Get the proper name for the file, as it will actually be saved.
    if name is None:
        name = content.name

    if not hasattr(content, 'chunks'):
        content = File(content, name)

    name = self.get_available_name(name, max_length=max_length)
    return self._save(name, content)

def generate_filename(self, filename):
    """
    Validate the filename by calling get_valid_name() and return a filename
    to be passed to the save() method.
    """
    # `filename` may include a path as returned by FileField.upload_to.
    dirname, filename = os.path.split(filename)
    if '..' in pathlib.PurePath(dirname).parts:
        raise SuspiciousFileOperation("Detected path traversal attempt in '%s'" % dirname)
    return os.path.normpath(os.path.join(dirname, self.get_valid_name(filename)))

def _save(self, name, content):
    full_path = self.path(name)

    # Create any intermediate directories that do not exist.
    directory = os.path.dirname(full_path)
    if not os.path.exists(directory):
        try:
            if self.directory_permissions_mode is not None:
                # Set the umask because os.makedirs() doesn't apply the "mode"
                # argument to intermediate-level directories.
                old_umask = os.umask(0o777 & ~self.directory_permissions_mode)
                try:
                    os.makedirs(directory, self.directory_permissions_mode)
                finally:
                    os.umask(old_umask)
            else:
                os.makedirs(directory)
        except FileExistsError:
            # There's a race between os.path.exists() and os.makedirs().
            # If os.makedirs() fails with FileExistsError, the directory
            # was created concurrently.
            pass
    if not os.path.isdir(directory):
        raise IOError("%s exists and is not a directory." % directory)

    # There's a potential race condition between get_available_name and
    # saving the file; it's possible that two threads might return the
    # same name, at which point all sorts of fun happens. So we need to
    # try to create the file, but if it already exists we have to go back
    # to get_available_name() and try again.

    while True:
        try:
            # This file has a file path that we can move.
            if hasattr(content, 'temporary_file_path'):
                file_move_safe(content.temporary_file_path(), full_path)

            # This is a normal uploadedfile that we can stream.
            else:
                # The current umask value is masked out by os.open!
                fd = os.open(full_path, self.OS_OPEN_FLAGS, 0o666)
                _file = None
                try:
                    locks.lock(fd, locks.LOCK_EX)
                    for chunk in content.chunks():
                        if _file is None:
                            mode = 'wb' if isinstance(chunk, bytes) else 'wt'
                            _file = os.fdopen(fd, mode)
                        _file.write(chunk)
                finally:
                    locks.unlock(fd)
                    if _file is not None:
                        _file.close()
                    else:
                        os.close(fd)
        except FileExistsError:
            # A new name is needed if the file exists.
            name = self.get_available_name(name)
            full_path = self.path(name)
        else:
            # OK, the file save worked. Break out of the loop.
            break

    if self.file_permissions_mode is not None:
        os.chmod(full_path, self.file_permissions_mode)

    # Store filenames with forward slashes, even on Windows.
    return name.replace('\\', '/')

def explain_query_prefix(self, format=None, **options):
    prefix = super().explain_query_prefix(format)
    extra = {}
    if format:
        extra["FORMAT"] = format
    if options:
        extra.update(
            {
                name.upper(): "true" if value else "false"
                for name, value in options.items()
            }
        )
    if extra:
        prefix += " (%s)" % ", ".join("%s %s" % i for i in extra.items())
    return prefix

def explain(self, using, format=None, **options):
    q = self.clone()
    q.explain_info = ExplainInfo(format, options)
    compiler = q.get_compiler(using=using)
    return "\n".join(compiler.explain_query())

