def add_extra(self, select, select_params, where, params, tables, order_by):
    """
    Add data to the various extra_* attributes for user-created additions
    to the query.
    """
    if select:
        # We need to pair any placeholder markers in the 'select'
        # dictionary with their parameters in 'select_params' so that
        # subsequent updates to the select dictionary also adjust the
        # parameters appropriately.
        select_pairs = {}
        if select_params:
            param_iter = iter(select_params)
        else:
            param_iter = iter([])
        for name, entry in select.items():
            entry = str(entry)
            entry_params = []
            pos = entry.find("%s")
            while pos != -1:
                if pos == 0 or entry[pos - 1] != '%':
                    entry_params.append(next(param_iter))
                pos = entry.find("%s", pos + 2)
            select_pairs[name] = (entry, entry_params)
        self.extra.update(select_pairs)
    if where or params:
        self.where.add(ExtraWhere(where, params), AND)
    if tables:
        self.extra_tables += tuple(tables)
    if order_by:
        self.extra_order_by = order_by

def stringToExpression(s, types, context):
    """Given a string, convert it to a tree of ExpressionNode's.
    """
    old_ctx = expressions._context.get_current_context()
    try:
        expressions._context.set_new_context(context)
        # first compile to a code object to determine the names
        if context.get('truediv', False):
            flags = __future__.division.compiler_flag
        else:
            flags = 0
        c = compile(s, '<expr>', 'eval', flags)
        # make VariableNode's for the names
        names = {}
        for name in c.co_names:
            if name == "None":
                names[name] = None
            elif name == "True":
                names[name] = True
            elif name == "False":
                names[name] = False
            else:
                t = types.get(name, default_type)
                names[name] = expressions.VariableNode(name, type_to_kind[t])
        names.update(expressions.functions)
        # now build the expression
        ex = eval(c, names)
        if expressions.isConstant(ex):
            ex = expressions.ConstantNode(ex, expressions.getKind(ex))
        elif not isinstance(ex, expressions.ExpressionNode):
            raise TypeError("unsupported expression type: %s" % type(ex))
    finally:
        expressions._context.set_new_context(old_ctx)
    return ex

def _get_ref_info_helper(
    cls, repo: "Repo", ref_path: Union[PathLike, None]
) -> Union[Tuple[str, None], Tuple[None, str]]:
    """Return: (str(sha), str(target_ref_path)) if available, the sha the file at
    rela_path points to, or None. target_ref_path is the reference we
    point to, or None"""
    if ".." in str(ref_path):
        raise ValueError(f"Invalid reference '{ref_path}'")
    tokens: Union[None, List[str], Tuple[str, str]] = None
    repodir = _git_dir(repo, ref_path)
    try:
        with open(os.path.join(repodir, str(ref_path)), "rt", encoding="UTF-8") as fp:
            value = fp.read().rstrip()
        # Don't only split on spaces, but on whitespace, which allows to parse lines like
        # 60b64ef992065e2600bfef6187a97f92398a9144                branch 'master' of git-server:/path/to/repo
        tokens = value.split()
        assert len(tokens) != 0
    except OSError:
        # Probably we are just packed, find our entry in the packed refs file
        # NOTE: We are not a symbolic ref if we are in a packed file, as these
        # are excluded explicitly
        for sha, path in cls._iter_packed_refs(repo):
            if path != ref_path:
                continue
            # sha will be used
            tokens = sha, path
            break
        # END for each packed ref
    # END handle packed refs
    if tokens is None:
        raise ValueError("Reference at %r does not exist" % ref_path)

    # is it a reference ?
    if tokens[0] == "ref:":
        return (None, tokens[1])

    # its a commit
    if repo.re_hexsha_only.match(tokens[0]):
        return (tokens[0], None)

    raise ValueError("Failed to parse reference information from %r" % ref_path)

async def handle_404(request, response):
    if 'json' not in response.headers['Content-Type']:
        if request.path.endswith('/'):
            return web.HTTPFound(request.path.rstrip('/'))
        return web.json_response({
            "status": 404,
            "message": "Page '{}' not found".format(request.path)
        }, status=404)
    return response

async def _handle(self, request: Request) -> StreamResponse:
    rel_url = request.match_info["filename"]
    try:
        filename = Path(rel_url)
        if filename.anchor:
            # rel_url is an absolute name like
            # /static/\\machine_name\c$ or /static/D:\path
            # where the static dir is totally different
            raise HTTPForbidden()
        filepath = self._directory.joinpath(filename).resolve()
        if not self._follow_symlinks:
            filepath.relative_to(self._directory)
    except (ValueError, FileNotFoundError) as error:
        # relatively safe
        raise HTTPNotFound() from error
    except HTTPForbidden:
        raise
    except Exception as error:
        # perm error or other kind!
        request.app.logger.exception(error)
        raise HTTPNotFound() from error

    # on opening a dir, load its contents if allowed
    if filepath.is_dir():
        if self._show_index:
            try:
                return Response(
                    text=self._directory_as_html(filepath), content_type="text/html"
                )
            except PermissionError:
                raise HTTPForbidden()
        else:
            raise HTTPForbidden()
    elif filepath.is_file():
        return FileResponse(filepath, chunk_size=self._chunk_size)
    else:
        raise HTTPNotFound

