def lookup_path(
    self, path: str
) -> typing.Tuple[str, typing.Optional[os.stat_result]]:
    for directory in self.all_directories:
        joined_path = os.path.join(directory, path)
        if self.follow_symlink:
            full_path = os.path.abspath(joined_path)
        else:
            full_path = os.path.realpath(joined_path)
        directory = os.path.realpath(directory)
        if os.path.commonprefix([full_path, directory]) != directory:
            # Don't allow misbehaving clients to break out of the static files
            # directory.
            continue
        try:
            return full_path, os.stat(full_path)
        except (FileNotFoundError, NotADirectoryError):
            continue
    return "", None

def get_header_lines(header):
    """
    Splits the header into lines, putting multi-line headers together.
    """
    r = []
    lines = header.split(b"\r\n")
    for line in lines:
        if b"\r" in line or b"\n" in line:
            raise ParsingError('Bare CR or LF found in header line "%s"' % tostr(line))

        if line.startswith((b" ", b"\t")):
            if not r:
                # https://corte.si/posts/code/pathod/pythonservers/index.html
                raise ParsingError('Malformed header line "%s"' % tostr(line))
            r[-1] += line
        else:
            r.append(line)
    return r

def _ensureSnapshotsFolder(self, subdir=None):
    """ Ensure that the appropriate snapshot folder exists.
    """
    path = ['snapshots', self._snapshot_id]

    if subdir is not None:
        path.extend(subdir.split('/'))

    current = self._tool

    for element in path:

        if element not in current.objectIds():
            # No Unicode IDs!
            current._setObject(str(element), Folder(element))

        current = current._getOb(element)

    return current

